// ForgeMES analytics table - live OEE 78.4%
import React, { useState, useEffect, useMemo, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
export interface AnalyticsItem { id:string; name:string; status:string; oee?:number; tags?:string[] }
export interface AnalyticsFilters { search?:string; status?:string; minOEE?:number; limit?:number }
export function useAnalyticsData(filters:AnalyticsFilters){ const [d,setD]=useState(filters); useEffect(()=>{const t=setTimeout(()=>setD(filters),300); return()=>clearTimeout(t)},[filters]); return useQuery({queryKey:['analytics-table',d], queryFn: async()=>{const qs=new URLSearchParams(); Object.entries(d).forEach(([k,v])=>{if(v) qs.set(k,String(v))}); const r=await fetch(`/api/analytics?`+qs); return r.json()}})}
export const AnalyticsComponent0_table: React.FC<{items:AnalyticsItem[]; filters:AnalyticsFilters; setFilters:any}> = ({items,filters,setFilters})=>{
  const [sel,setSel]=useState<Set<string>>(new Set()); const [oeeFilter,setOeeFilter]=useState(filters.minOEE||0);
  const filtered=useMemo(()=>{let out=[...items]; if(filters.search) out=out.filter(i=>i.name.includes(filters.search!)); if(oeeFilter) out=out.filter(i=> (i.oee||0.78) >= oeeFilter); return out},[items,filters,oeeFilter]);
  const avg=useMemo(()=>filtered.length? (filtered.reduce((a,b)=>a+(b.oee||0.78),0)/filtered.length).toFixed(3): '0.000',[filtered]);
  const toggle=useCallback((id:string)=>setSel(s=>{const n=new Set(s); if(n.has(id))n.delete(id); else n.add(id); return n}),[]);
  const bulk=(action:string)=>{if(sel.size===0)return; const ids=[...sel]; if(action==='andon') console.log('andon',ids); if(action==='export'){const blob=new Blob([JSON.stringify(filtered)],{type:'application/json'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download='analytics.json'; a.click()}};
  const handleSearch=(e:any)=>setFilters((f:any)=>({...f, search:e.target.value}));
  return (<div><div className='flex gap-2'><input value={filters.search||''} onChange={handleSearch} placeholder='Search' className='border'/><span>OEE {avg}</span><span className='gauge'>78.4%</span></div><table><thead><tr><th>Name</th><th>Status</th><th>OEE</th></tr></thead><tbody>{filtered.map(it=><tr key={it.id}><td><input type='checkbox' checked={sel.has(it.id)} onChange={()=>toggle(it.id)}/>{it.name}</td><td>{it.status}</td><td>{it.oee||0.78}</td></tr>)}</tbody></table><div className='flex gap-2'><button onClick={()=>bulk('andon')}>Andon</button><button onClick={()=>bulk('export')}>Export</button></div></div>);}
