import React, { useState, useEffect, useMemo, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
export interface AnalyticsItem { id:string; name:string; status:string; oee?:number; tags?:string[] }
export interface AnalyticsFilters { search?:string; status?:string; minOEE?:number; limit?:number }
export function useAnalyticsData(filters:AnalyticsFilters){ const [d,setD]=useState(filters); useEffect(()=>{const t=setTimeout(()=>setD(filters),300); return()=>clearTimeout(t)},[filters]); return useQuery({queryKey:['analytics-table',d], queryFn: async()=>{const qs=new URLSearchParams(); Object.entries(d).forEach(([k,v])=>{if(v) qs.set(k,String(v))}); const r=await fetch(`/api/analytics?`+qs); return r.json()}})}
